#!/bin/bash
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-26
# Driver: upgrade every Isaac -fishdeterministic image to -fishfastid (scripts/migrate_fastdds_identity.sh: rmw_fastrtps sample
# identity + in-place rebuild of the intra-process users), then optionally the validation run + pipeline per family
# (scripts/fastdds1_validate.sh). One family after another; old tags untouched.
# Usage: scripts/migrate_fastdds_all.sh <log_dir> [family ...]      (default: the 17 TASK 4 families)
#   env: RUN=1 (default 0) run fastdds1_validate.sh after a successful migration; HOST_SPLIT=1 put the host in split mode for
#        the runs (off again at the end); SKIP_EXISTING=1 (default 1) do not rebuild an existing -fishfastid image
set -u; cd "$(dirname "$0")/.."
LD=${1:?log dir}; shift; mkdir -p "$LD"; RUN=${RUN:-0}
log() { echo "[$(date +%T)] $*" | tee -a "$LD/migrate_fastdds_all.txt"; }
FAMS="$*"; [ -z "$FAMS" ] && FAMS="apriltag bi3d bi3d_freespace detectnet dnn_image_encoder dope ess image_proc nitros_bridge nvblox rtdetr segformer stereo_image_proc tensor_rt triton unet visual_slam"
[ "${HOST_SPLIT:-0}" = 1 ] && [ "$RUN" = 1 ] && { sudo -n /usr/local/sbin/fish-host-perf-mode split >> "$LD/migrate_fastdds_all.txt" 2>&1 || log "split failed; runs unconfined"; }
for F in $FAMS; do
  [ -f "$LD/STOP" ] && { log "STOP file present; exit"; break; }
  BASE=fish-r2b-$F-fishdeterministic:latest; NEW=fish-r2b-$F-fishfastid:latest
  docker image inspect $BASE >/dev/null 2>&1 || { log "$F: base $BASE missing"; continue; }
  if [ "${SKIP_EXISTING:-1}" = 1 ] && docker image inspect $NEW >/dev/null 2>&1; then log "$F: $NEW exists, skipping build"; else
    T0=$SECONDS; LOG="$LD/migrate_$F.log" bash scripts/migrate_fastdds_identity.sh $BASE $NEW ros2_benchmark isaac_ros_benchmark >/dev/null 2>&1
    R=$(grep -c "^COMMITTED" "$LD/migrate_$F.log"); log "$F: migrate $( [ "$R" = 1 ] && echo OK || echo FAILED ) in $((SECONDS - T0)) s ($(grep -o "FASTDDS_TEST.*" "$LD/migrate_$F.log" | head -1); $(grep -o "intra_take hook instantiations: [0-9]*" "$LD/migrate_$F.log" | tr '\n' ' '))"
    [ "$R" = 1 ] || continue
  fi
  if [ "$RUN" = 1 ]; then
    T0=$SECONDS; bash scripts/fastdds1_validate.sh "$F" "$LD" >/dev/null 2>&1; log "$F: validation run done in $((SECONDS - T0)) s: $(grep "^$F,lttng" "$LD/runs/runs.csv" 2>/dev/null | tail -1)"
  fi
done
[ "${HOST_SPLIT:-0}" = 1 ] && [ "$RUN" = 1 ] && sudo -n /usr/local/sbin/fish-host-perf-mode off >> "$LD/migrate_fastdds_all.txt" 2>&1
log "ALL DONE"
